#include <algorithm>
#include <iostream>
#include <numeric>
#include <vector>

int main() {
    const std::vector<int> values{4, 1, 9, 3};
    const int total = std::accumulate(values.begin(), values.end(), 0);
    std::cout << "sum=" << total << ", min=" << *std::min_element(values.begin(), values.end())
              << ", max=" << *std::max_element(values.begin(), values.end()) << '\n';
}
